import sys, json
changes_from_historical = []
for line in sys.stdin:
    rec = json.loads(line)
    case_id = rec['case_id']
    accepted = rec['accepted']
    # Expected changes based on fixes
    if case_id in ['c02_zero_weight_source', 'c03_single_source', 'c04_legacy_manifest']:
        if accepted:
            changes_from_historical.append(f'{case_id}: REJECT->ACCEPT (fixed)')
    elif case_id in ['c06_non_integer_total', 'c08_composition_not_the_experiment', 'c13_expected_total_mismatch']:
        if not accepted:
            changes_from_historical.append(f'{case_id}: ACCEPT->REJECT (fixed)')

if len(changes_from_historical) == 6:
    print('All 6 expected case decision changes confirmed:')
    for change in sorted(changes_from_historical):
        print(f'  ✓ {change}')
else:
    print(f'WARNING: Expected 6 changes, found {len(changes_from_historical)}')
    for change in changes_from_historical:
        print(f'  {change}')
"

